// Port of mozc/src/base/password_manager.{h,cc} (3.35.6354). macOS uses the
// "WinMacPasswordManager": a random 32-byte session password is stored in
// <user profile>/.encrypt_key.db, encrypted with Encryptor.protectData
// (key derived from the Mac serial number and the uid). The file is made
// read-only (0400) except while being written.
//
// PasswordManager is a class for managing a password (passphrase) used for
// user-data encryption. It doesn't save user password, but save a session
// password automatically generated by mozc.

import Synchronization

#if canImport(Darwin)
  import Darwin
#endif

public enum PasswordManager {
  private static let kPasswordFile = ".encrypt_key.db"  // dot-file (hidden file)
  private static let kPasswordSize = 32
  // Serializes the access to the password file (there is no in-memory state).
  private static let mutex = Mutex(())

  private static func createRandomPassword() -> [UInt8] {
    var random = Random()
    return random.byteString(kPasswordSize)
  }

  // RAII helper to make a given file writable/read-only.
  private static func withReadWriteFile<R>(_ filename: String, _ body: () -> R) -> R {
    if FileUtil.fileExistsOK(filename) {
      chmod(filename, 0o600)  // write temporary
    } else {
      GenmaiLog.warning("file not found: \(filename)")
    }
    defer {
      if FileUtil.fileExistsOK(filename) {
        chmod(filename, 0o400)  // read only
      } else {
        GenmaiLog.warning("file not found: \(filename)")
      }
    }
    return body()
  }

  private static func getFileName() -> String {
    FileUtil.joinPath(SystemUtil.getUserProfileDirectory(), kPasswordFile)
  }

  private static func savePassword(_ password: [UInt8]) -> Bool {
    let filename = getFileName()
    return withReadWriteFile(filename) {
      do {
        try FileUtil.setContents(filename, password)
        return true
      } catch {
        GenmaiLog.error("Cannot save password: \(error)")
        return false
      }
    }
  }

  private static func loadPassword() -> [UInt8]? {
    let filename = getFileName()
    let mmap: Mmap
    do {
      mmap = try Mmap.map(filename, .readOnly)
    } catch {
      GenmaiLog.error("cannot open: \(filename): \(error)")
      return nil
    }
    // Typical file size is 32 * 5 = 160byte.
    // We just set the maximum file size to be 4096byte just in case.
    if mmap.isEmpty || mmap.size > 4096 {
      GenmaiLog.error("Invalid password is saved")
      return nil
    }
    return [UInt8](mmap.data)
  }

  private static func removePasswordFile() -> Bool {
    let filename = getFileName()
    return withReadWriteFile(filename) {
      do {
        try FileUtil.unlink(filename)
        return true
      } catch {
        GenmaiLog.error("Cannot unlink \(filename): \(error)")
        return false
      }
    }
  }

  // MARK: WinMacPasswordManager

  private static func setPasswordImpl(_ password: [UInt8]) -> Bool {
    if password.count != kPasswordSize {
      GenmaiLog.error("password size is invalid")
      return false
    }
    guard let encPassword = Encryptor.protectData(password) else {
      GenmaiLog.error("ProtectData failed")
      return false
    }
    return savePassword(encPassword)
  }

  private static func getPasswordImpl() -> [UInt8]? {
    guard let encPassword = loadPassword() else {
      GenmaiLog.error("LoadPassword failed")
      return nil
    }
    guard let password = Encryptor.unprotectData(encPassword) else {
      GenmaiLog.error("UnprotectData failed")
      return nil
    }
    if password.count != kPasswordSize {
      GenmaiLog.error("password size is invalid")
      return nil
    }
    return password
  }

  private static func initPasswordUnlocked() -> Bool {
    if getPasswordImpl() != nil {
      return true
    }
    return setPasswordImpl(createRandomPassword())
  }

  // MARK: Public API

  /// Initialize password.
  /// If password is not found, make a random password internally.
  /// return false if initialization failed.
  /// Do nothing and return true if password is found.
  public static func initPassword() -> Bool {
    mutex.withLock { _ in initPasswordUnlocked() }
  }

  /// get current password. Call initPassword() if need be.
  public static func getPassword() -> [UInt8]? {
    mutex.withLock { _ in
      if let password = getPasswordImpl() {
        return password
      }
      GenmaiLog.warning("Cannot get password. call InitPassword")
      if !initPasswordUnlocked() {
        GenmaiLog.error("InitPassword failed")
        return nil
      }
      guard let password = getPasswordImpl() else {
        GenmaiLog.error("Cannot get password.")
        return nil
      }
      return password
    }
  }

  /// remove current password
  public static func removePassword() -> Bool {
    mutex.withLock { _ in removePasswordFile() }
  }
}
